package com.badrulamin.University_Management.service; import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.FacultyAttendance; import com.badrulamin.University_Management.repository.FacultyAttendanceRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;  import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.List;  @Service @RequiredArgsConstructor public class FacultyAttendanceService {      private final FacultyAttendanceRepository facultyAttendanceRepository;      public Page<FacultyAttendance> findAll(Pageable pageable) {         return facultyAttendanceRepository.findAll(pageable);     }      public FacultyAttendance findById(Long id) {         return facultyAttendanceRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("FacultyAttendance", "id", id));     }      public FacultyAttendance save(FacultyAttendance facultyAttendance) {         return facultyAttendanceRepository.save(facultyAttendance);     }      public FacultyAttendance update(Long id, FacultyAttendance facultyAttendance) {         findById(id);         facultyAttendance.setId(id);         return facultyAttendanceRepository.save(facultyAttendance);     }      public void delete(Long id) {         findById(id);         facultyAttendanceRepository.deleteById(id);     } }